// Creates a new contact markdown file from template.md for a brand-new
// contact (e.g. one discovered via a Gmail label with no existing file — see
// "Full Repo Access" / "Gmail Labels for Category Routing" in CLAUDE.md).
// gmail-sync only updates contacts that already have a file; this script is
// the manual step that creates one.
import * as fs from "node:fs";
import * as path from "node:path";

const ROOT = path.resolve(__dirname, "..");
const TEMPLATE_PATH = path.join(ROOT, "template.md");

export const CATEGORY_DIRS: Record<string, string> = {
  client: "client",
  colleague: "colleagues",
  friend: "friends",
};

export function slugify(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // strip accents
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function makeFilename(
  lastName: string,
  firstName: string,
  email: string,
  usedFilenames: Set<string>
): string {
  let base: string;
  if (lastName && firstName) {
    base = slugify(`${lastName}-${firstName}`);
  } else if (lastName) {
    base = slugify(lastName);
  } else if (firstName) {
    base = slugify(firstName);
  } else {
    base = slugify(email.split("@")[0]);
  }
  if (!base) base = slugify(email.replace("@", "-at-"));

  let filename = base;
  if (usedFilenames.has(filename)) {
    const domain = email.split("@")[1]?.split(".")[0] || "dup";
    filename = `${base}-${slugify(domain)}`;
  }
  let final = filename;
  let counter = 2;
  while (usedFilenames.has(final)) {
    final = `${filename}-${counter}`;
    counter++;
  }
  return `${final}.md`;
}

export function splitName(name: string): { firstName: string; lastName: string } {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return { firstName: "", lastName: "" };
  if (parts.length === 1) return { firstName: parts[0], lastName: "" };
  return { firstName: parts.slice(0, -1).join(" "), lastName: parts[parts.length - 1] };
}

export function buildFrontmatter(
  lastName: string,
  firstName: string,
  emails: string[],
  today: string
): string {
  const lines = ["---"];
  lines.push(`last_name: ${lastName}`);
  lines.push(`first_name: ${firstName}`);
  if (emails.length > 1) {
    lines.push("emails:");
    for (const e of emails) lines.push(`  - "${e}"`);
  } else {
    lines.push(`email: "${emails[0]}"`);
  }
  lines.push(`last_updated: ${today}`);
  lines.push("---");
  return lines.join("\n");
}

export function parseArgs(argv: string[]) {
  let name = "";
  let category = "";
  const emails: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--name") name = argv[++i] ?? "";
    else if (a === "--email") emails.push((argv[++i] ?? "").trim());
    else if (a === "--category") category = argv[++i] ?? "";
  }
  return { name: name.trim(), category: category.trim(), emails: emails.filter(Boolean) };
}

// Finds a contact file, anywhere under root's client/colleagues/friends dirs,
// whose raw content mentions `email` (case-insensitive substring match, same
// approach gmail-sync-adjacent tooling uses for frontmatter scanning).
export function findExistingContact(email: string, root: string): string | null {
  const needle = email.toLowerCase();
  for (const dir of ["client", "colleagues", "friends"]) {
    const abs = path.join(root, dir);
    if (!fs.existsSync(abs)) continue;
    for (const f of fs.readdirSync(abs)) {
      if (!f.endsWith(".md")) continue;
      const raw = fs.readFileSync(path.join(abs, f), "utf-8").toLowerCase();
      if (raw.includes(needle)) return `${dir}/${f}`;
    }
  }
  return null;
}

export type CreateContactResult =
  | { status: "created"; relPath: string }
  | { status: "duplicate"; email: string; existing: string }
  | { status: "invalid-category" }
  | { status: "no-email" }
  | { status: "invalid-email"; email: string };

export interface CreateContactOptions {
  name: string;
  category: string;
  emails: string[];
  root: string;
  today: string;
  templatePath: string;
}

// Filesystem-touching core, parameterized by root/templatePath so callers
// (tests) can point it at a throwaway directory instead of the live repo.
export function createContact(opts: CreateContactOptions): CreateContactResult {
  const { name, category, emails, root, today, templatePath } = opts;

  if (!CATEGORY_DIRS[category]) return { status: "invalid-category" };
  if (emails.length === 0) return { status: "no-email" };
  for (const e of emails) {
    if (!e.includes("@")) return { status: "invalid-email", email: e };
  }
  for (const e of emails) {
    const existing = findExistingContact(e, root);
    if (existing) return { status: "duplicate", email: e, existing };
  }

  const { firstName, lastName } = splitName(name);

  const dir = CATEGORY_DIRS[category];
  const dirAbs = path.join(root, dir);
  fs.mkdirSync(dirAbs, { recursive: true });
  const usedFilenames = new Set(
    fs.readdirSync(dirAbs).map((f) => f.replace(/\.md$/, ""))
  );
  const filename = makeFilename(lastName, firstName, emails[0], usedFilenames);

  const template = fs.readFileSync(templatePath, "utf-8");
  const body = template.slice(template.indexOf("\n## Notes"));
  const content = `${buildFrontmatter(lastName, firstName, emails, today)}\n${body}`;

  fs.writeFileSync(path.join(dirAbs, filename), content, "utf-8");
  return { status: "created", relPath: `${dir}/${filename}` };
}

function main() {
  const argv = process.argv.slice(2);
  if (argv.includes("--help") || argv.length === 0) {
    console.error(
      "Usage: npm run create-contact -- --name \"First Last\" --email a@b.com [--email c@d.com ...] --category client|colleague|friend\n" +
        "Creates a new contact file from template.md. Refuses if the email already exists in another contact file."
    );
    process.exit(argv.length === 0 ? 1 : 0);
  }

  const { name, category, emails } = parseArgs(argv);
  const today = new Date().toISOString().slice(0, 10);
  const result = createContact({ name, category, emails, root: ROOT, today, templatePath: TEMPLATE_PATH });

  switch (result.status) {
    case "invalid-category":
      console.error(`--category must be one of: ${Object.keys(CATEGORY_DIRS).join(", ")}`);
      process.exit(1);
    case "no-email":
      console.error("At least one --email is required.");
      process.exit(1);
    case "invalid-email":
      console.error(`Not a valid email address: ${result.email}`);
      process.exit(1);
    case "duplicate":
      console.error(`⚠️  ${result.email} already appears in ${result.existing} — not creating a duplicate.`);
      process.exit(1);
    case "created":
      console.log(`✍️  Created ${result.relPath}`);
  }
}

if (require.main === module) main();
